import sys
from collections import deque

def findShortestPath(matrix):
    R = len(matrix)
    C = len(matrix[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < R and 0 <= y < C and matrix[x][y] == 1

    queue = deque()
    visited = set()

    for i in range(R):
        if matrix[i][0] == 1:
            queue.append((i, 0, 1))
            visited.add((i, 0))

    while queue:
        x, y, dist = queue.popleft()

        if y == C - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

def main():
    import sys
    import json
    input_data = sys.stdin.read().strip()
    matrix = json.loads(input_data)
    result = findShortestPath(matrix)
    print(result)

if __name__ == "__main__":
    main()
